package com.networkmonitorpro.ui.adapter; import android.view.*;import android.widget.*;import androidx.recyclerview.widget.*;import com.networkmonitorpro.R;import com.networkmonitorpro.data.entity.NotificationHistory;import java.text.*;import java.util.*; public class HistoryAdapter extends RecyclerView.Adapter<HistoryAdapter.VH>{ private List<NotificationHistory> data=new ArrayList<>(); public void submit(List<NotificationHistory>d){data=d==null?new ArrayList<>():d;notifyDataSetChanged();} public VH onCreateViewHolder(ViewGroup p,int v){return new VH(LayoutInflater.from(p.getContext()).inflate(R.layout.item_history,p,false));} public void onBindViewHolder(VH h,int p){NotificationHistory n=data.get(p);h.t.setText(n.title);h.s.setText(n.message+" • "+DateFormat.getDateTimeInstance().format(new Date(n.timestamp)));} public int getItemCount(){return data.size();} static class VH extends RecyclerView.ViewHolder{TextView t,s;VH(View v){super(v);t=v.findViewById(R.id.title);s=v.findViewById(R.id.subtitle);}} }
